        free(v0); free(vp); free(vi); free(w); free(Av);
        csr_destroy(A);
        return 1;
    }

    init_random_vector(v0, n);
    vec_copy(v0, vp, n);
    vec_copy(v0, vi, n);

    /* Power iteration for lambda_max */
    int power_converged = 0;
    int power_iterations = 0;
    double lambda_max = NAN;
    double prev_lambda_max = NAN;

    for (int iter = 0; iter < maxiter; iter++) {
        csr_spmv(A, vp, w);
        lambda_max = vec_dot(vp, w, n);
        double nrm = vec_norm2(w, n);
        if (nrm < 1e-300) {
            break;
        }
        for (int i = 0; i < n; i++) vp[i] = w[i] / nrm;

        power_iterations = iter + 1;
        if (!isnan(prev_lambda_max) && fabs(lambda_max) > 0.0) {
            if (fabs(lambda_max - prev_lambda_max) / fabs(lambda_max) < tol) {
                power_converged = 1;
                break;
            }
        }
        prev_lambda_max = lambda_max;
    }

    /* Inverse iteration for lambda_min */
    int inverse_converged = 0;
    int inverse_iterations = 0;
    double lambda_min = NAN;
    double prev_lambda_min = NAN;

    for (int iter = 0; iter < maxiter; iter++) {
        int fail = 0;
        SolveResult *res = solve_linear_system(A, vi, solver, precond, solver_tol, solver_maxiter, restart, omega, &fail);
        if (!res || !res->converged || fail) {
            lambda_min = NAN;
            if (res) solve_result_destroy(res);
            break;
        }
        double wnorm = vec_norm2(res->x, n);
        if (wnorm < 1e-300) {
            lambda_min = NAN;
            solve_result_destroy(res);
            break;
        }
        double rq = vec_dot(vi, res->x, n);
        if (fabs(rq) < 1e-300) {
            lambda_min = NAN;
            solve_result_destroy(res);
            break;
        }
        lambda_min = 1.0 / rq;
        for (int i = 0; i < n; i++) w[i] = res->x[i] / wnorm;
        memcpy(vi, w, n * sizeof(double));
        solve_result_destroy(res);

        inverse_iterations = iter + 1;
        if (!isnan(prev_lambda_min) && fabs(lambda_min) > 0.0) {
            if (fabs(lambda_min - prev_lambda_min) / fabs(lambda_min) < tol) {
                inverse_converged = 1;
                break;
            }
        }
        prev_lambda_min = lambda_min;
    }

    double condition_number;
    if (isnan(lambda_max) || isnan(lambda_min) || lambda_min == 0.0) {
        condition_number = INFINITY;
    } else {
        condition_number = fabs(lambda_max) / fabs(lambda_min);
    }

    printf("lambda_max: %.15e\n", lambda_max);
    printf("lambda_min: %.15e\n", lambda_min);
    printf("condition_number: %.15e\n", condition_number);
    printf("power_iterations: %d\n", power_iterations);
    printf("inverse_iterations: %d\n", inverse_iterations);
    printf("power_converged: %s\n", power_converged ? "yes" : "no");
    printf("inverse_converged: %s\n", inverse_converged ? "yes" : "no");

    free(v0); free(vp); free(vi); free(w); free(Av);
    csr_destroy(A);
    return 0;
}
